fn solve(r: i8, g: i8, b: i8) -> i8 {
    // Lift to i32 to avoid overflow when summing up to 3*127 = 381
    let (r, g, b) = (r as i32, g as i32, b as i32);

    // Compute floor((r + g + b) / 3)
    let total_tables = (r + g + b) / 3;

    // Compute pairwise sums
    let rg = r + g;
    let rb = r + b;
    let gb = g + b;

    // The answer is the minimum of these four values
    let answer = total_tables.min(rg).min(rb).min(gb);

    // Cast back to i8; by problem statement the result is guaranteed to fit
    answer as i8
}

